(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    var customerCode = source.getValue('u_customer');

    // Skip if blank or not an active customer in the CLM master
    if (gs.nil(customerCode) || !CLMCustomerCache.has(customerCode)) {
        ignore = true;
    }

})(source, map, log, target);
